script:
const subject = `${ctx.testPrefix} ${ctx.val('tieu_de', 'Thư tự động')}`;
const to = ctx.list('nguoi_nhan');
if (!to.length) to.push(ctx.username);   // bắt buộc có người nhận: để trống thì gửi cho chính tài khoản đang chạy
const cc = ctx.list('cc');               // tùy chọn: để trống thì bỏ qua

// Hai ô người nhận (Đến, CC) là hai khung .hrw-treecompany-box. Mỗi ô có một danh sách gợi ý riêng (.t-s-menu__comboBox),
// được tạo khi ô nhận con trỏ lần đầu (Đến trước, CC sau). Danh sách của ô kia vẫn hiện nên phải chọn đúng danh sách theo thứ tự ô.
const box = i => page.locator('.hrw-treecompany-box').nth(i);
const suggestions = i => page.locator('.t-s-menu__comboBox').nth(i).locator('li.t-s-item');
const addPeople = async (i, codes, key) => {
  for (const code of codes) {
    const input = box(i).locator('input.hrv-next-input');
    await input.focus();   // focus thay vì click: danh sách gợi ý của ô khác có thể che ô này; sau khi có người, ô Đến mất placeholder
    await input.pressSequentially(code);
    await pickOption(suggestions(i), key, code);   // chờ danh sách lọc xong (mất vài giây) rồi chọn đúng mã
  }
};

await step('Mở form Tạo thư mới', async () => {
  await page.waitForLoadState('networkidle', { timeout: 20000 }).catch(() => {});
  await box(0).waitFor({ timeout: 20000 });
});

await step(`Chọn người nhận (Đến): ${to.join(', ')}`, async () => { await addPeople(0, to, 'nguoi_nhan'); });

if (cc.length) await step(`Chọn người nhận CC: ${cc.join(', ')}`, async () => { await addPeople(1, cc, 'cc'); });
else ctx.log('CC để trống, bỏ qua');

await step('Nhập tiêu đề và nội dung', async () => {
  const title = page.locator('input[placeholder="Tiêu đề:"]');
  await title.focus();
  await title.pressSequentially(subject);
  if (!ctx.has('noi_dung')) { ctx.log('Nội dung để trống, bỏ qua (chỉ có chữ ký)'); return; }
  // Nội dung là trình soạn thảo CKEditor; chữ chèn lên đầu, chữ ký có sẵn nằm bên dưới
  const editor = page.locator('.ck-editor__editable');
  await editor.focus();
  await page.keyboard.press('Control+Home');
  await page.keyboard.type(ctx.val('noi_dung'));
});

await step('Đính kèm file (nếu có)', async () => {
  // Ô file đính kèm nằm trong .file-upload; ô input[type=file] còn lại của CKEditor chỉ để chèn ảnh vào nội dung
  const attached = await attachFiles(page.locator('.file-upload input[type=file]'), 'tep_dinh_kem');
  if (!attached) { ctx.log('Không có file đính kèm, bỏ qua'); return; }
  await page.locator('.form-new__attachment__name').first().waitFor({ timeout: 30000 });
});

await step('Bấm Gửi, thư được gửi và quay về Hộp thư đến', async () => {
  const send = page.getByRole('button', { name: 'Gửi', exact: true });
  await send.click({ timeout: 8000 }).catch(() => send.dispatchEvent('click'));
  // Gửi mất vài giây (nút ở trạng thái đang tải, có thông báo "Thư đang được gửi.")
  await page.waitForURL(/\/internal_mailold\/inbox/, { timeout: 90000 });
});

await step('Thư xuất hiện trong Hộp thư đến', async () => {
  // Thư gửi cho chính mình mới hiện ở Hộp thư đến; gửi cho người khác thì kiểm tra ở mục Đã gửi
  if (to.some(c => c.toLowerCase() === String(ctx.username).toLowerCase())) {
    await page.locator('tbody tr .mail-content__subject', { hasText: subject }).first().waitFor({ timeout: 30000 });
  } else {
    ctx.log('Không gửi cho chính mình nên không kiểm tra Hộp thư đến');
  }
});
ctx.log('Đã gửi thư: ' + subject);
